let cachedLandMaskPath = "";

let cachedKey = "";
let cachedLandPath = "";

function offsetAt(schedule, timestamp) {
    let offset = schedule[0];
    for (let index = 1; index < schedule.length; index += 2) {
        if (timestamp < schedule[index])
            break;
        offset = schedule[index + 1];
    }
    return offset;
}

function landPathForOffset(offsetSeconds, timestamp) {
    const wantedOffset = Math.round(Number(offsetSeconds) || 0);
    const instant = Number(timestamp) || Date.now();
    const key = wantedOffset + ":" + Math.floor(instant / 60000);
    if (key === cachedKey)
        return cachedLandPath;

    let path = "";
    for (const timezone in LAND_PATHS) {
        if (offsetAt(OFFSET_SCHEDULES[timezone], instant) === wantedOffset)
            path += LAND_PATHS[timezone];
    }
    cachedKey = key;
    cachedLandPath = path;
    return path;
}

function oceanBandForOffset(offsetSeconds) {
    const offset = Math.round(Number(offsetSeconds) || 0);
    if (offset % 3600 !== 0 || offset < -12 * 3600 || offset > 12 * 3600)
        return { "x": 0, "width": 0 };
    const center = (offset / 3600 * 15 + 180) * 2;
    const left = Math.max(0, center - 15);
    return { "x": left, "width": Math.min(720, center + 15) - left };
}

function landMaskPath() {
    if (cachedLandMaskPath.length > 0)
        return cachedLandMaskPath;
    let path = "";
    for (const timezone in LAND_PATHS)
        path += LAND_PATHS[timezone];
    cachedLandMaskPath = path;
    return path;
}
